server.registerTool(
  "create_market_report",
  {
    title: "Create market report",
    description: "Create and persist a timestamped premarket, intraday, postmarket, or research report. Returns structured data and a localhost dashboard URL. It never places orders.",
    inputSchema: {
      symbols: external_exports.array(external_exports.string().min(1)).min(1).max(20).optional().describe("Uses saved watchlist when omitted"),
      phase: external_exports.enum(["premarket", "intraday", "postmarket", "research"]).optional().default("research"),
      includeNews: external_exports.boolean().optional().default(true),
      positions: external_exports.array(positionSchema).max(50).optional()
    }
  },
  async (input) => {
    try {
      const report = await createMarketReport({ ...input, enrichReport });
      const compact = {
        runId: report.runId,
        generatedAt: report.generatedAt,
        phase: report.phase,
        summary: report.summary,
        items: report.items.map(({ history, news, ...item }) => ({
          ...item,
          news: news?.slice(0, 3),
          historyPoints: history?.length ?? 0
        })),
        dashboardUrl: report.dashboardUrl,
        latestDashboardUrl: report.latestDashboardUrl,
        sourceNotice: report.sourceNotice
      };
      return toolResult(
        compact,
        `${report.phaseLabel}\u5DF2\u751F\u6210\uFF1A${report.latestDashboardUrl}`
      );
    } catch (error2) {
      return toolError(error2);
    }
  }
);
