function registerWorkspaceTool(name, description, inputSchema, action) {
  server.registerTool(
    name,
    { title: name.replaceAll("_", " "), description, inputSchema },
    async (input) => {
      try {
        return toolResult(await action(input), description);
      } catch (error2) {
        return toolError(error2);
      }
    }
  );
}
